package com.ecommerce.user_service.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="user_action_tokens")public class UserActionToken{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id",nullable=false)private User user;@Column(name="token_hash",nullable=false,unique=true,length=64)private String tokenHash;@Column(nullable=false,length=24)private String purpose;@Column(name="expires_at",nullable=false)private LocalDateTime expiresAt;@Column(name="consumed_at")private LocalDateTime consumedAt;protected UserActionToken(){}public UserActionToken(User user,String hash,String purpose,LocalDateTime expiresAt){this.user=user;tokenHash=hash;this.purpose=purpose;this.expiresAt=expiresAt;}public Long getId(){return id;}public User getUser(){return user;}public LocalDateTime getExpiresAt(){return expiresAt;}public LocalDateTime getConsumedAt(){return consumedAt;}public void consume(){consumedAt=LocalDateTime.now();}}
